// src/pages/Shops.jsx
import { useState } from "react";
import C from "../constants/colors";
import { SHOPS_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import Btn from "../components/ui/Btn";

function Shops({ t }) {
  const [search, setSearch] = useState("");

  // ── Translation strings ───────────────────────────────────────────────────
  const TX = {
    title:      t("shops.title")    || "Agri Shops Near You",
    subtitle:   t("shops.subtitle") || "Find agricultural shops, fertilizer dealers and veterinary clinics near you",
    search:     t("shops.search")   || "Search shops…",
    open:       t("shops.open")     || "Open",
    closed:     t("shops.closed")   || "Closed",
    call:       t("shops.call")     || "Call",
    distance:   t("shops.distance") || "km away",
    rating:     t("shops.rating")   || "Rating",
    products:   t("shops.products") || "Available Products",
    directions: "📍 Get Directions",
    noResults:  t("common.noData")  || "No shops found",
    phone:      t("profile.phone")  || "Phone",
    address:    t("map.location")   || "Address",
  };

  const filtered = (SHOPS_DATA || []).filter(s =>
    s.name.toLowerCase().includes(search.toLowerCase()) ||
    (s.address || "").toLowerCase().includes(search.toLowerCase())
  );

  const handleGetDirections = (shop) => {
    const query = encodeURIComponent(`${shop.name}, ${shop.address}`);
    window.open(`https://www.google.com/maps/search/?api=1&query=${query}`, "_blank");
  };

  const handleCall = (phone) => {
    if (phone) window.open(`tel:${phone}`);
  };

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>
        🏪 {TX.title}
      </h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 14px" }}>{TX.subtitle}</p>

      {/* Search */}
      <input
        value={search}
        onChange={e => setSearch(e.target.value)}
        placeholder={TX.search}
        style={{
          width:        "100%",
          maxWidth:     320,
          padding:      "10px 12px",
          borderRadius: 8,
          border:       `1px solid ${C.border}`,
          fontSize:     13,
          outline:      "none",
          marginBottom: 14,
          color:        C.text,
        }}
      />

      {/* No results */}
      {filtered.length === 0 && (
        <div style={{ textAlign: "center", padding: "40px 0", color: C.muted, fontSize: 14 }}>
          {TX.noResults}
        </div>
      )}

      {/* Shop grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 12 }}>
        {filtered.map((shop, i) => (
          <Card key={i} style={{ padding: 14 }}>

            {/* Shop name + open/closed badge */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
              <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{shop.name}</div>
              {shop.isOpen !== undefined && (
                <span style={{
                  fontSize:     10.5,
                  fontWeight:   600,
                  padding:      "2px 8px",
                  borderRadius: 10,
                  background:   shop.isOpen ? "#e8f8ee" : "#fff0f0",
                  color:        shop.isOpen ? C.bg2 : C.red,
                }}>
                  {shop.isOpen ? TX.open : TX.closed}
                </span>
              )}
            </div>

            {/* Details */}
            <div style={{ fontSize: 12, color: C.muted, marginBottom: 12, lineHeight: 1.7 }}>
              📍 {shop.address || "Address not available"}<br />
              📞 {shop.phone   || "Phone not available"}<br />
              ⭐ {TX.rating}: {shop.rating || "N/A"}
              {shop.distance && <><br />📏 {shop.distance} {TX.distance}</>}
            </div>

            {/* Products */}
            {shop.products?.length > 0 && (
              <div style={{ marginBottom: 10 }}>
                <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, marginBottom: 5, textTransform: "uppercase", letterSpacing: "0.04em" }}>
                  {TX.products}
                </div>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                  {shop.products.slice(0, 4).map(p => (
                    <span key={p} style={{ fontSize: 11, padding: "2px 7px", background: C.pale, borderRadius: 10, color: C.bg2 }}>{p}</span>
                  ))}
                </div>
              </div>
            )}

            {/* Action buttons */}
            <div style={{ display: "flex", gap: 7 }}>
              <Btn
                onClick={() => handleGetDirections(shop)}
                style={{ flex: 1, padding: "8px", fontSize: 12 }}
              >
                {TX.directions}
              </Btn>
              {shop.phone && (
                <Btn
                  variant="outline"
                  onClick={() => handleCall(shop.phone)}
                  style={{ padding: "8px 12px", fontSize: 12 }}
                >
                  📞 {TX.call}
                </Btn>
              )}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

export default Shops;
